package com.randbox.randombox;
import com.mojang.brigadier.CommandDispatcher;import com.mojang.brigadier.arguments.IntegerArgumentType;import com.randbox.randombox.loot.BoxTier;import com.randbox.randombox.network.*;import net.minecraft.commands.*;import net.minecraft.commands.arguments.ResourceLocationArgument;import net.minecraft.commands.arguments.coordinates.BlockPosArgument;import net.minecraft.core.BlockPos;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.commands.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.level.block.entity.ChestBlockEntity;import net.minecraftforge.network.PacketDistributor;
public final class Commands {public static void register(CommandDispatcher<CommandSourceStack>d){d.register(net.minecraft.commands.Commands.literal("RandomBox").requires(s->s.hasPermission(2)).then(net.minecraft.commands.Commands.literal("SetNewBox").then(net.minecraft.commands.Commands.argument("pos",BlockPosArgument.blockPos()).then(net.minecraft.commands.Commands.argument("quality",IntegerArgumentType.integer(0,5)).then(net.minecraft.commands.Commands.argument("loot_table",ResourceLocationArgument.id()).executes(c->{BlockPos p=BlockPosArgument.getLoadedBlockPos(c,"pos");int q=IntegerArgumentType.getInteger(c,"quality");ResourceLocation table=ResourceLocationArgument.getId(c,"loot_table");c.getSource().getLevel().setBlockAndUpdate(p,Blocks.CHEST.defaultBlockState());if(c.getSource().getLevel().getBlockEntity(p)instanceof ChestBlockEntity chest){chest.setLootTable(table,c.getSource().getLevel().random.nextLong());if(q>0)chest.getPersistentData().putInt("RandomBoxTier",q);chest.setChanged();}c.getSource().sendSuccess(()->net.minecraft.network.chat.Component.literal("Random box created at "+p.toShortString()),true);return 1;}))))).then(net.minecraft.commands.Commands.literal("GUI").executes(c->{ServerPlayer p=c.getSource().getPlayerOrException();Net.CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new OpenEditorPacket());return 1;})));}}
